export class NodeRedisAdapter {
    client;
    constructor(client) {
        this.client = client;
    }
    hset(key, fields) {
        return this.client.hSet(key, fields);
    }
    hgetall(key) {
        return this.client.hGetAll(key);
    }
    hdel(key, ...fields) {
        return this.client.hDel(key, fields);
    }
    del(...keys) {
        return this.client.del(keys);
    }
    sadd(key, ...members) {
        return this.client.sAdd(key, members);
    }
    srem(key, ...members) {
        return this.client.sRem(key, members);
    }
    smembers(key) {
        return this.client.sMembers(key);
    }
    rpush(key, ...values) {
        return this.client.rPush(key, values);
    }
    lrange(key, start, stop) {
        return this.client.lRange(key, start, stop);
    }
    lindex(key, index) {
        return this.client.lIndex(key, index);
    }
    lset(key, index, value) {
        return this.client.lSet(key, index, value);
    }
    llen(key) {
        return this.client.lLen(key);
    }
    xadd(key, id, fields) {
        return this.client.xAdd(key, id, fields);
    }
    async xread(streams, options = {}) {
        const result = await this.client.xRead(streams.map((stream) => ({ key: stream.key, id: stream.xid })), { BLOCK: options.block, COUNT: options.count });
        if (!result)
            return [];
        return result.map((stream) => ({
            key: stream.name,
            messages: stream.messages.map((message) => ({ id: message.id, data: message.message })),
        }));
    }
    xgroupCreate(key, group, id, mkstream) {
        return this.client.xGroupCreate(key, group, id, { MKSTREAM: mkstream });
    }
    async xreadgroup(streams, options) {
        const result = await this.client.xReadGroup(options.group, options.consumer, streams.map((s) => ({ key: s.key, id: s.xid })), { BLOCK: options.block, COUNT: options.count });
        if (!result)
            return [];
        return result.map((stream) => ({
            key: stream.name,
            messages: stream.messages.map((msg) => ({ id: msg.id, data: msg.message })),
        }));
    }
    xack(key, group, ...ids) {
        return this.client.xAck(key, group, ids);
    }
    keys(pattern) {
        return this.client.keys(pattern);
    }
    scan(cursor, options) {
        return this.client.scan(cursor, options);
    }
    exists(...keys) {
        return this.client.exists(keys);
    }
    expire(key, seconds) {
        return this.client.expire(key, seconds);
    }
    set(key, value, options) {
        const opts = {
            NX: options?.nx ? true : undefined,
            PX: options?.px,
            EX: options?.ex,
        };
        return this.client.set(key, value, opts);
    }
    get(key) {
        return this.client.get(key);
    }
    // Redis server-side Lua (EVAL). Not JavaScript eval; runs the given script
    // atomically inside Redis for compare-and-delete / compare-and-pexpire.
    eval(script, keys, args) {
        return this.client.eval(script, { keys, arguments: args });
    }
    quit() {
        // redis v5: quit() renamed to close()
        return this.client.close();
    }
    disconnect() {
        // redis v5: disconnect() renamed to destroy()
        return Promise.resolve().then(() => this.client.destroy());
    }
}
